<?php
namespace App\Http\Controllers; use App\Models\Expense; use Illuminate\Http\Request; class ExpenseController extends Controller {public function index(){return view('expenses.index',['expenses'=>Expense::latest('expense_date')->paginate(20)]);} public function store(Request $r){Expense::create($r->validate(['expense_date'=>'required|date','title'=>'required|string|max:255','category'=>'nullable|string|max:100','amount'=>'required|numeric|min:0.01','notes'=>'nullable|string']));return back()->with('success','Expense save ho gaya.');} public function destroy(Expense $expense){$expense->delete();return back()->with('success','Expense delete ho gaya.');}}
